import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import {emptyPlan,createAuthoringTools,templateFrom,changeSummary,directionMatches,startProfiles} from '../../reda-2/plan-authoring-model.mjs';
const ctx={console};ctx.window=ctx;ctx.globalThis=ctx;vm.createContext(ctx);
for(const f of ['data.js','clinical-model-v2.js','clinical-addons.js','clinical-library-v3.js','exercise-intelligence-knee.js','exercise-intelligence-next.js','exercise-quality.js','core.js','planner.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),ctx);
const P=ctx.RedaPlanner,T=createAuthoringTools(P,ctx.RedaData);
test('manual entry has no inferred clinical direction or package inclusion',()=>{const p=emptyPlan({patientName:'Fictional',goal:'Walk'});assert.equal(p.exercises.length,0);assert.equal(p.authoring.includedInVisit,false);assert.equal(p.context.blueprintId,undefined);assert.equal(p.goal,'Walk')});
test('manual ordination preserves full instructions, variants and individual edits while reordering',()=>{let p=T.add(T.add(emptyPlan(),'chair'),'extension');p=P.editExercise(p,0,{reps:7,prescribedLoad:'Individual effort',prescribedRange:'Individually assessed'});p.progressionDraft={old:true};const moved=T.move(p,0,1);assert.equal(moved.exercises[1].dose.reps,7);assert.equal(moved.exercises[1].prescribedLoad,'Individual effort');assert.ok(moved.exercises.every(x=>x.motionKey&&x.instructions.length&&x.dose.label));assert.equal(moved.progressionDraft,undefined);assert.equal(T.remove(moved,0).exercises[0].id,'chair');assert.throws(()=>T.add(p,'chair'),/redan/)});
test('adaptation retains compatible choices and exact edited doses, flags unresolved floor exercise',()=>{let p=T.add(T.add(emptyPlan({floorOK:true,band:true}),'chair'),'bridge');p=P.editExercise(p,0,{reps:7});const next=T.adapt(p,{floorOK:false});assert.equal(next.exercises[0].dose.reps,7);assert.ok(next.warnings.some(x=>x.includes('Höftlyft')));assert.equal(p.context.floorOK,true);assert.equal(T.remove(next,1).warnings.length,0);assert.ok(changeSummary(p,next).includes('Uppdatera planens förutsättningar'))});
test('a reusable template excludes every patient-specific field and is rebuilt from library',()=>{let p=T.add(emptyPlan({patientName:'SECRET',goal:'PRIVATE',clinicianNote:'NOTE'}),'extension');p=P.editExercise(p,0,{side:'left',reps:9,prescribedLoad:'SECRET LOAD',prescribedRange:'SECRET RANGE'});p.progressionDraft={secret:'RULE'};const template=templateFrom(p);assert.equal(/SECRET|PRIVATE|NOTE|RULE|left/.test(JSON.stringify(template)),false);const rebuilt=T.fromTemplate(template,{patientName:'New patient',goal:'New goal'});assert.equal(rebuilt.patientName,'New patient');assert.equal(rebuilt.goal,'New goal');assert.equal(rebuilt.exercises[0].dose.reps,9);assert.equal(rebuilt.exercises[0].prescribedLoad,undefined);assert.equal(rebuilt.exercises[0].prescribedRange,undefined);assert.equal(rebuilt.exercises[0].side,'both');assert.ok(rebuilt.exercises[0].instructions.length)});
test('invalid template variants cannot silently become a different exercise',()=>{assert.throws(()=>T.fromTemplate({exercises:[{id:'chair',variantId:'invented',dose:{reps:8}}]},{}),/Ingen variant/);assert.throws(()=>T.add(emptyPlan({floorOK:false}),'bridge'),/Ingen variant/)});
test('body region matching presents alternatives without diagnosing from free text',()=>{const b=Object.values(P.liveBlueprints()),matches=directionMatches('Vänster knä',b);assert.ok(matches.length>1);assert.equal(directionMatches('Unknown',b).length,0);assert.ok(matches.every(x=>/knä|knee/i.test(x.name+' '+x.id)));assert.equal(startProfiles.supported.values.floorOK,false)});
test('bilateral variants do not accept unilateral side values',()=>{const p=T.add(emptyPlan(),'chair');assert.equal(P.allowedSides(p.exercises[0].id,p.exercises[0].variantId).includes('left'),false);const x=T.exercise('extension');assert.ok(P.allowedSides(x.id,x.variantId).includes('left'))});
